(6184186, 912297, 99392, '<td valign="top">Very creative and well executed!</td>', 'Very creative and well executed!', '2010-10-07 02:35:22.000000', NULL, 1),
(6184229, 912649, 120174, '<td valign="top">I would have given you a mark hihger, if it wasnt for the hair!!!</td>', 'I would have given you a mark hihger, if it wasnt for the hair!!!', '2010-10-07 04:48:30.000000', NULL, 1),
(6184266, 912657, 101702, '<td valign="top">A really good action shot - great expressions, but I''m just not getting any link to the challenge topic of "metal on metal".</td>', 'A really good action shot - great expressions, but I''m just not getting any link to the challenge topic of "metal on metal".', '2010-10-07 05:49:40.000000', NULL, 1),
(6184270, 912219, 101702, '<td valign="top">Cleverly done!</td>', 'Cleverly done!', '2010-10-07 06:00:03.000000', NULL, 1),
(6184278, 913014, 101702, '<td valign="top">One of two 9''s I gave out - ribbon contender. The lighting is expertly done, and the setup is something so different from everything else in the challenge that I applaud your creativity.</td>', 'One of two 9''s I gave out - ribbon contender. The lighting is expertly done, and the setup is something so different from everything else in the challenge that I applaud your creativity.', '2010-10-07 06:14:53.000000', NULL, 1),
(6184282, 912858, 101702, '<td valign="top">I gave out two 9''s and three 8''s in this challenge (my top 5). Yours is one of them. I think without the car top left this would have been a much cleaner shot and I probably would have given it a 10.</td>', 'I gave out two 9''s and three 8''s in this challenge (my top 5). Yours is one of them. I think without the car top left this would have been a much cleaner shot and I probably would have given it a 10.', '2010-10-07 06:22:12.000000', NULL, 1),
(6184285, 913008, 101702, '<td valign="top">I gave out two 9''s and three 8''s in this challenge (my top 5). You are one of them. Great choice of colour for the overall lighting / filter which really adds to the mood. It''s a shame this is basic editing because of the little flaws and scratches here and there. I would like to see this after an advanced edit.</td>', 'I gave out two 9''s and three 8''s in this challenge (my top 5). You are one of them. Great choice of colour for the overall lighting / filter which really adds to the mood. It''s a shame this is basic editing because of the little flaws and scratches here and there. I would like to see this after an advanced edit.', '2010-10-07 06:24:21.000000', NULL, 1),
(6184287, 913149, 101702, '<td valign="top">I gave out two 9''s and three 8''s in this challenge (my top 5). Great compositional angle and good use of the reflection. The B&amp;W conversion add that extra little something over the other zipper shots in the challenge.</td>', 'I gave out two 9''s and three 8''s in this challenge (my top 5). Great compositional angle and good use of the reflection. The B&W conversion add that extra little something over the other zipper shots in the challenge.', '2010-10-07 06:25:52.000000', NULL, 1),
(6184290, 912966, 101702, '<td valign="top">One of only two 9''s I gave out in this challenge - ribbon contender. I really like the compositional angle, the warm yet subdued lighting which really compliments the wood, and the focus is perfect on the nearest peg. My only worry is whether the border will get you a DQ. Is this type of border legal in basic?</td>', 'One of only two 9''s I gave out in this challenge - ribbon contender. I really like the compositional angle, the warm yet subdued lighting which really compliments the wood, and the focus is perfect on the nearest peg. My only worry is whether the border will get you a DQ. Is this type of border legal in basic?', '2010-10-07 06:29:30.000000', NULL, 1),
(6184409, 913014, 21810, '<td valign="top">I like this, very... Burtonesque ;)</td>', 'I like this, very... Burtonesque ;)', '2010-10-07 09:02:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6184590, 912793, 85430, '<td valign="top">interesting subject.</td>', 'interesting subject.', '2010-10-07 12:27:23.000000', NULL, 1),
(6184593, 912875, 85430, '<td valign="top">interesting photo. but i see some noise in the dark areas. maybe a lower iso would have cleaned up the overall image.</td>', 'interesting photo. but i see some noise in the dark areas. maybe a lower iso would have cleaned up the overall image.', '2010-10-07 12:30:45.000000', NULL, 1),
(6184595, 913126, 85430, '<td valign="top">perfect angle. effective use of leading lines. the composition of this image is very remarkable</td>', 'perfect angle. effective use of leading lines. the composition of this image is very remarkable', '2010-10-07 12:33:31.000000', NULL, 1),
(6184597, 912970, 85430, '<td valign="top">good composition. effective use of shapes. the reflected light was just enough not to blow up the highlights, and yet there was enough shadows to offer a good contrast. i like this image very much</td>', 'good composition. effective use of shapes. the reflected light was just enough not to blow up the highlights, and yet there was enough shadows to offer a good contrast. i like this image very much', '2010-10-07 12:35:50.000000', NULL, 1),
(6184598, 913038, 85430, '<td valign="top">the angle from which the shot was taken was not the best one. the strong flash at the left side of the image is a bit distracting.</td>', 'the angle from which the shot was taken was not the best one. the strong flash at the left side of the image is a bit distracting.', '2010-10-07 12:37:42.000000', NULL, 1),
(6184602, 913106, 85430, '<td valign="top">good choice of colors. perfect framing. and the sharpness is just right. this is a very good shot. but unfortunately, i feel this is a photo of another person''s craftmanship. i would have given this a very high rating had the subject been different, but the shot of the same execution.</td>', 'good choice of colors. perfect framing. and the sharpness is just right. this is a very good shot. but unfortunately, i feel this is a photo of another person''s craftmanship. i would have given this a very high rating had the subject been different, but the shot of the same execution.', '2010-10-07 12:42:57.000000', NULL, 1),
(6184604, 913150, 99981, '<td valign="top">It''s such a simple subject but it got my attention and i liked it. Nice texture, composition and light. Maybe it''s my monitor but the shadows are looking a little noisy to me. Nice work though...</td>', 'It''s such a simple subject but it got my attention and i liked it. Nice texture, composition and light. Maybe it''s my monitor but the shadows are looking a little noisy to me. Nice work though...', '2010-10-07 12:44:46.000000', NULL, 1),
(6184605, 913099, 85430, '<td valign="top">it fits the challenge. this image would have been good had the subject been isolated from the background. a little contrast would have helped too.</td>', 'it fits the challenge. this image would have been good had the subject been isolated from the background. a little contrast would have helped too.', '2010-10-07 12:46:03.000000', NULL, 1),
(6184609, 912903, 85430, '<td valign="top">nice use of dof, but i feel the background is still a bit busy with the wide range of lights and shadows, which is distracting. a closer crop, or perhaps a different angle to take advantage of a cleaner background would have made this image better.  overall, i still give this a high vote.</td>', 'nice use of dof, but i feel the background is still a bit busy with the wide range of lights and shadows, which is distracting. a closer crop, or perhaps a different angle to take advantage of a cleaner background would have made this image better.  overall, i still give this a high vote.', '2010-10-07 12:49:32.000000', NULL, 1),
(6184613, 912464, 85430, '<td valign="top">white backgrounds usually work for jewelry, food, smiling faces and other "mild" and "peaceful" objects. but a hammer and nail, is a very strong image. to some it may even imply violence and force. For me, a darker background would have justified this image better. other than that, this is a very interesting take on the challenge. nice.</td>', 'white backgrounds usually work for jewelry, food, smiling faces and other "mild" and "peaceful" objects. but a hammer and nail, is a very strong image. to some it may even imply violence and force. For me, a darker background would have justified this image better. other than that, this is a very interesting take on the challenge. nice.', '2010-10-07 12:55:21.000000', NULL, 1),
(6184616, 912402, 85430, '<td valign="top">very well executed. the colors are just right. the sun is captured just at the right angle and placement. the lighting on the foreground is a bit harsh, but overall, this is a very nice photo</td>', 'very well executed. the colors are just right. the sun is captured just at the right angle and placement. the lighting on the foreground is a bit harsh, but overall, this is a very nice photo', '2010-10-07 12:57:44.000000', NULL, 1),
(6184618, 912571, 85430, '<td valign="top">fits the challenge really well. the image is well exposed, although i think the lighting was a bit flat. some shadows would have given this image more dimensions.</td>', 'fits the challenge really well. the image is well exposed, although i think the lighting was a bit flat. some shadows would have given this image more dimensions.', '2010-10-07 13:02:08.000000', NULL, 1),
(6184622, 913084, 85430, '<td valign="top">i once had a honda c50, and it was the same color and probably the same age as this. it rusted away in our garage just like this one, but i was never able to capture a photo of it just like how you did it here. the shadows say a lot about the dark storage you have for this old bike. the framing (cropping?) is just right. any more of the bike''s body would have made the image less interesting. very nice photo.</td>', 'i once had a honda c50, and it was the same color and probably the same age as this. it rusted away in our garage just like this one, but i was never able to capture a photo of it just like how you did it here. the shadows say a lot about the dark storage you have for this old bike. the framing (cropping?) is just right. any more of the bike''s body would have made the image less interesting. very nice photo.', '2010-10-07 13:09:01.000000', NULL, 1),
(6184625, 912710, 85430, '<td valign="top">the composition, the choice of subject, and the execution was great in this photo. my only comment is about the choice of sepia tone, which doesn''really go well with steel and tin. other than that, i give this a high rating.</td>', 'the composition, the choice of subject, and the execution was great in this photo. my only comment is about the choice of sepia tone, which doesn''really go well with steel and tin. other than that, i give this a high rating.', '2010-10-07 13:11:28.000000', NULL, 1),
