(6185329, 913067, 36843, '<td valign="top">cool I have a trex</td>', 'cool I have a trex', '2010-10-07 22:26:18.000000', NULL, 1),
(6185331, 913141, 85430, '<td valign="top">it meets the challenge. i like the overall tones of the color. good contrast. but the subject doesn''t seem to be very interesting.</td>', 'it meets the challenge. i like the overall tones of the color. good contrast. but the subject doesn''t seem to be very interesting.', '2010-10-07 22:27:29.000000', NULL, 1),
(6185340, 913043, 85430, '<td valign="top">i find the subject a little too dark. maybe a better lighting could make the image stronger.</td>', 'i find the subject a little too dark. maybe a better lighting could make the image stronger.', '2010-10-07 22:30:09.000000', NULL, 1),
(6185355, 912888, 85430, '<td valign="top">i was planning to submit a similar entry. yours is a good capture. the lighting is just right. the dark background makes the subject stand out. this could sell as a stock photo.</td>', 'i was planning to submit a similar entry. yours is a good capture. the lighting is just right. the dark background makes the subject stand out. this could sell as a stock photo.', '2010-10-07 22:34:32.000000', NULL, 1),
(6185390, 912500, 85430, '<td valign="top">you liked the negative image challenge a lot? but this one has a good composition. and i think the subject still meets the challenge. i have to give it a low score though for having unnatural colors.</td>', 'you liked the negative image challenge a lot? but this one has a good composition. and i think the subject still meets the challenge. i have to give it a low score though for having unnatural colors.', '2010-10-07 22:40:29.000000', NULL, 1),
