INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6187724, 913058, 94241, '<td valign="top">Beautiful use of color.  :)<br/> <br/>When you shoot a reflective object like this, you can use one or more white bedsheets to make a "tent" that surrounds your subject and the table its on.  That makes for really nice smooth reflection.  Using a more narrow depth of field helps as well: the reflections are very far away compared to the surface of the subject they''re reflecting on.</td>', 'Beautiful use of color.  :) When you shoot a reflective object like this, you can use one or more white bedsheets to make a "tent" that surrounds your subject and the table its on.  That makes for really nice smooth reflection.  Using a more narrow depth of field helps as well: the reflections are very far away compared to the surface of the subject they''re reflecting on.', '2010-10-10 18:27:10.000000', NULL, 1),
(6187726, 912919, 94241, '<td valign="top">Cutting shapes off at the frame edge gives a journalistic, loose and free and "in the moment" feel to it.  But the subject of this photo is more structured, architectural, and considered.  So this is a way of me saying, I like this photo, but I think it would be a smidge stronger if the circular shape on top wasn''t cut off.  Maybe the S-hook on the right too, but not totally sure about that one.</td>', 'Cutting shapes off at the frame edge gives a journalistic, loose and free and "in the moment" feel to it.  But the subject of this photo is more structured, architectural, and considered.  So this is a way of me saying, I like this photo, but I think it would be a smidge stronger if the circular shape on top wasn''t cut off.  Maybe the S-hook on the right too, but not totally sure about that one.', '2010-10-10 18:30:35.000000', NULL, 1),
(6187754, 912054, 94241, '<td valign="top">I absolutely love this photo.<br/> <br/>If I could nitpick one thing, I''d say it bugs me a bit that the shape is cut off by the bottom edge.  I think that a timeless, structural, considered subject needs a structural frame.  Cutting the shape off I think makes it feel a little more loose and free.</td>', 'I absolutely love this photo. If I could nitpick one thing, I''d say it bugs me a bit that the shape is cut off by the bottom edge.  I think that a timeless, structural, considered subject needs a structural frame.  Cutting the shape off I think makes it feel a little more loose and free.', '2010-10-10 19:24:15.000000', NULL, 1),
(6187945, 913070, 119823, '<td valign="top">Great shot! love this.</td>', 'Great shot! love this.', '2010-10-11 00:03:17.000000', NULL, 1),
(6187946, 913014, 119823, '<td valign="top">Wow! I think this is the winner!</td>', 'Wow! I think this is the winner!', '2010-10-11 00:04:21.000000', NULL, 1),
