(6189456, 912474, 27812, '<td valign="top">This is a +- 1900 Wilkinson bayonet for the .303 rifle, used during the Anglo Boer war and the first World War. I have one too, mine a 1902 inherited from my Great-Grandfather. Great photograph!</td>', 'This is a +- 1900 Wilkinson bayonet for the .303 rifle, used during the Anglo Boer war and the first World War. I have one too, mine a 1902 inherited from my Great-Grandfather. Great photograph!', '2010-10-12 14:58:44.000000', NULL, 1),
(6189458, 913105, 121827, '<td valign="top">very unique.</td>', 'very unique.', '2010-10-12 15:01:45.000000', NULL, 1),
