(6189528, 913035, 99708, '<td valign="top">Not sure if you were going for a blurred effect, but for me as a viewer, it doesn''t work for this shot.</td>', 'Not sure if you were going for a blurred effect, but for me as a viewer, it doesn''t work for this shot.', '2010-10-12 16:28:12.000000', NULL, 1),
