(6189546, 913138, 47470, '<td valign="top">I love the simplicity.  I wish the ring was centered to match the symmetry of the rest of the image.</td>', 'I love the simplicity.  I wish the ring was centered to match the symmetry of the rest of the image.', '2010-10-12 17:08:32.000000', NULL, 1),
(6189549, 912868, 47470, '<td valign="top">Normally I wouldn''t like to use such an industrial background for something like wedding rings, which are supposed to be soft/frilly/sparkly, but the repetition of all the circles works very well.</td>', 'Normally I wouldn''t like to use such an industrial background for something like wedding rings, which are supposed to be soft/frilly/sparkly, but the repetition of all the circles works very well.', '2010-10-12 17:10:55.000000', NULL, 1),
(6189597, 913131, 54446, '<td valign="top">Excellent multiple exposure in one frame.  My fav in the challenge.</td>', 'Excellent multiple exposure in one frame.  My fav in the challenge.', '2010-10-12 18:22:19.000000', NULL, 1),
(6189599, 912710, 54446, '<td valign="top">Cool image.  Definitely meets the challenge well.</td>', 'Cool image.  Definitely meets the challenge well.', '2010-10-12 18:22:41.000000', NULL, 1),
