(6189803, 912793, 67697, '<td valign="top">This is cool.  Love the waves of water and the spot of light.</td>', 'This is cool.  Love the waves of water and the spot of light.', '2010-10-12 22:44:15.000000', NULL, 1),
(6189820, 912874, 47470, '<td valign="top">The lighting on the hammer could be improved so it wouldn''t blend in with the background near the top.  I wish there was a way to make the sparks stand out because theya re what make the image so interesting!</td>', 'The lighting on the hammer could be improved so it wouldn''t blend in with the background near the top.  I wish there was a way to make the sparks stand out because theya re what make the image so interesting!', '2010-10-12 23:20:04.000000', NULL, 1),
